api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
/* =========================================================
   CAMPUS CONNECT — UPCOMING EVENTS
   ========================================================= */

.cc-events-section {
    width: 120%;
    padding: 8px 100px 28px 100px;
    box-sizing: border-box;
    font-family: "Segoe UI", Arial, sans-serif;
}


/* =========================================================
   SECTION HEADER
   ========================================================= */

.cc-section-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 18px;
}

.cc-section-header h2 {
    margin: 0;
    color: #102a43;
    font-size: 21px;
    font-weight: 700;
    line-height: 1.3;
}

.cc-section-header p {
    margin: 5px 0 0 0;
    color: #718096;
    font-size: 12px;
}


/* =========================================================
   VIEW ALL
   ========================================================= */

.cc-view-all {
    display: inline-flex;
    align-items: center;
    color: #0879e8 !important;
    font-size: 12px;
    font-weight: 600;
    text-decoration: none !important;
    cursor: pointer;
}

.cc-view-all:hover {
    color: #005bb5 !important;
    text-decoration: none !important;
}


/* =========================================================
   EVENT ROW
   ========================================================= */

.cc-event-row {
    margin-left: -7px;
    margin-right: -7px;
}

.cc-event-row > div {
    padding-left: 7px;
    padding-right: 7px;
    margin-bottom: 14px;
}


/* =========================================================
   EVENT CARD
   ========================================================= */

.cc-event-card {
    min-height: 285px;
    padding: 18px;
    box-sizing: border-box;

    background: #ffffff;

    border: 1px solid #dce5ef;
    border-radius: 10px;

    box-shadow: 0 4px 14px rgba(20, 45, 80, 0.06);

    transition:
        transform 0.18s ease,
        box-shadow 0.18s ease,
        border-color 0.18s ease;
}

.cc-event-card:hover {
    transform: translateY(-3px);

    border-color: #b9cde3;

    box-shadow:
        0 9px 22px rgba(20, 45, 80, 0.11);
}


/* =========================================================
   EVENT TOP
   ========================================================= */

.cc-event-top {
    display: flex;
    align-items: center;
    justify-content: space-between;

    margin-bottom: 13px;
}


/* Event Type */

.cc-event-type {
    display: inline-flex;
    align-items: center;

    padding: 5px 9px;

    background: #eaf3ff;

    border-radius: 5px;

    color: #0866c6;

    font-size: 10px;
    font-weight: 700;

    text-transform: capitalize;
}


/* Fee */

.cc-event-fee {
    color: #1f7a4d;

    font-size: 11px;
    font-weight: 700;
}


/* =========================================================
   EVENT TITLE
   ========================================================= */

.cc-event-card h3 {
    margin: 0 0 8px 0;

    color: #102a43;

    font-size: 17px;
    font-weight: 700;

    line-height: 1.35;

    min-height: 45px;
}


/* =========================================================
   TECHNOLOGY TAGS
   ========================================================= */

.cc-tags {
    margin: 0 0 13px 0;

    color: #0879e8;

    font-size: 11px;
    font-weight: 600;

    line-height: 1.5;
}


/* =========================================================
   EVENT INFORMATION
   ========================================================= */

.cc-event-info {
    margin: 6px 0;

    color: #52677d;

    font-size: 11px;

    line-height: 1.4;
}

.cc-info-icon {
    display: inline-block;

    width: 20px;

    font-size: 12px;
}


/* =========================================================
   MAP BUTTON
   ========================================================= */

.cc-map-btn {
    display: inline-block;

    margin-top: 3px;
    margin-bottom: 12px;

    color: #0879e8 !important;

    font-size: 11px;
    font-weight: 600;

    text-decoration: none !important;

    cursor: pointer;
}

.cc-map-btn:hover {
    color: #005bb5 !important;

    text-decoration: underline !important;
}


/* =========================================================
   ACTION BUTTONS
   ========================================================= */

.cc-event-actions {
    display: flex;

    align-items: center;

    gap: 8px;

    margin-top: 8px;
}


/* Details */

.cc-details-btn {
    flex: 1;

    height: 34px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #ffffff;

    border: 1px solid #cbd8e8;

    border-radius: 5px;

    color: #23415f !important;

    font-size: 11px;
    font-weight: 600;

    text-decoration: none !important;

    cursor: pointer;

    transition: all 0.15s ease;
}

.cc-details-btn:hover {
    background: #f5f9fd;

    border-color: #9fb7d0;

    color: #102a43 !important;

    text-decoration: none !important;
}


/* Register */

.cc-register-btn {
    flex: 1;

    height: 34px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #0879e8;

    border: 1px solid #0879e8;

    border-radius: 5px;

    color: #ffffff !important;

    font-size: 11px;
    font-weight: 600;

    text-decoration: none !important;

    cursor: pointer;

    transition: all 0.15s ease;
}

.cc-register-btn:hover {
    background: #0668c7;

    border-color: #0668c7;

    color: #ffffff !important;

    text-decoration: none !important;
}


/* =========================================================
   NO EVENTS
   ========================================================= */

.cc-no-events {
    padding: 45px 20px;

    text-align: center;

    background: #ffffff;

    border: 1px solid #dce5ef;

    border-radius: 10px;
}

.cc-no-events-icon {
    font-size: 32px;

    margin-bottom: 10px;
}

.cc-no-events h3 {
    margin: 0 0 6px 0;

    color: #102a43;

    font-size: 17px;
}

.cc-no-events p {
    margin: 0;

    color: #718096;

    font-size: 12px;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 992px) {

    .cc-events-section {
        padding: 8px 20px 24px 20px;
    }

    .cc-event-card {
        margin-bottom: 14px;
    }

}


@media (max-width: 600px) {

    .cc-events-section {
        padding: 8px 15px 20px 15px;
    }

    .cc-section-header {
        align-items: flex-start;
        flex-direction: column;

        gap: 8px;
    }

    .cc-section-header h2 {
        font-size: 19px;
    }

    .cc-event-card {
        min-height: auto;
    }

}

sp_widget.script:
(function() {

    data.events = [];

    var eventGR = new GlideRecord('x_snc_campus_con_0_events');

    // Only verified events
    eventGR.addQuery('verification_status', 'verified');

    // Include today's events and future events
    // Compare only the calendar date
    var today = new GlideDate();
    eventGR.addQuery('event_date', '>=', today.getValue());

    // Nearest events first
    eventGR.orderBy('event_date');

    // Maximum 3 events
    eventGR.setLimit(3);

    eventGR.query();

    while (eventGR.next()) {

        var feeDisplay = eventGR.getDisplayValue('fees');

        if (!feeDisplay || feeDisplay == '0') {
            feeDisplay = 'Free';
        }

        data.events.push({

            // Event sys_id
            sys_id: eventGR.getUniqueValue(),

            // Event name
            event_name: eventGR.getDisplayValue('event_name'),

            // Organizer
            organizer: eventGR.getDisplayValue('organizer'),

            // Event date
            event_date: eventGR.getDisplayValue('event_date'),

            // Location
            location: eventGR.getDisplayValue('location'),

            // Event type
            event_type: eventGR.getDisplayValue('event_type'),

            // Technology tags
            technology_tags: eventGR.getDisplayValue('technology_tags'),

            // Fees
            fees: feeDisplay,

            // Verification status
            verification_status: eventGR.getDisplayValue('verification_status'),

            // Google Maps URL
            google_maps_link: eventGR.getValue('google_maps_link')

        });

    }

})();
